const fs=require('fs'),path=require('path'),{spawnSync}=require('child_process');
const {createOwnedTemporaryDirectory,removeOwnedTemporaryDirectory}=require('./tinyrustlm/tools/canonical-operation-scratch.js');
const owned=createOwnedTemporaryDirectory({temporaryParent:path.resolve('artifacts/tests/admission-lifetime')});
try{
 const args=['--experimental-test-coverage','--test-coverage-include=tinyrustlm/app/catalog-admission-loader.js','--test','tinyrustlm/tests/catalog-admission-loader.test.js','tinyrustlm/tests/model-acquisition.test.js','tinyrustlm/tests/model-acquisition-boundary-regression.test.js','tinyrustlm/tests/p2p-composition-install.test.js','tinyrustlm/tests/model-composition-store.test.js','tinyrustlm/tests/static-shell-parity.test.js'];
 const r=spawnSync(process.execPath,args,{cwd:process.cwd(),env:{...process.env,TEMP:owned.rootPath,TMP:owned.rootPath,TMPDIR:owned.rootPath,NODE_V8_COVERAGE:path.join(owned.rootPath,'coverage')},windowsHide:true,encoding:'utf8',timeout:60000,maxBuffer:2*1024*1024});
 const out=r.stdout||'';process.stdout.write(out.slice(out.lastIndexOf('\u2139 tests')));if(r.status!==0)process.stdout.write(out);process.stderr.write(r.stderr||'');if(r.error)throw r.error;process.exitCode=r.status===0?0:1;
}finally{
 let files=0,bytes=0;function count(p){for(const e of fs.readdirSync(p,{withFileTypes:true})){const n=path.join(p,e.name);if(e.isDirectory())count(n);else{files++;bytes+=fs.statSync(n).size;}}}count(owned.rootPath);removeOwnedTemporaryDirectory(owned);console.log(JSON.stringify({ownedRemoved:true,files,logicalBytes:bytes}));
}
